operations.replacement_region_source:
let input = (*ctxt).input;
let mut input_cur = (*input).cur;
if *input_cur as c_int == '\n' as i32 {
    (*input).line += 1;
    (*input).col = 1 as c_int;
} else {
    (*input).col += 1;
}
(*ctxt).token = 0 as c_int;
input_cur = input_cur.offset(l as isize);
(*input).cur = input_cur;
if nbchar >= HTML_PARSER_BIG_BUFFER_SIZE {
    // SAFETY: nbchar is used as a write position into `buf`, whose capacity is 1006;
    // this flush path is reached only after appends bounded by that fixed buffer size,
    // and the original code writes the terminating 0 at this exact index.
    unsafe { *buf.get_unchecked_mut(nbchar as usize) = 0 as xmlChar; }
    let sax = (*ctxt).sax;
    if !sax.is_null() && (*ctxt).disableSAX == 0 {
        if areBlanks(ctxt, &raw mut buf as *mut xmlChar, nbchar) != 0 {
            if (*ctxt).keepBlanks != 0 {
                let characters = (*sax).characters;
                if characters.is_some() {
                    characters.expect("non-null function pointer")(
                        (*ctxt).userData,
                        &raw mut buf as *mut xmlChar,
                        nbchar,
                    );
                }
            } else {
                let ignorable_whitespace = (*sax).ignorableWhitespace;
                if ignorable_whitespace.is_some() {
                    ignorable_whitespace.expect("non-null function pointer")(
                        (*ctxt).userData,
                        &raw mut buf as *mut xmlChar,
                        nbchar,
                    );
                }
            }
        } else {
            htmlCheckParagraph(ctxt);
            let characters = (*sax).characters;
            if characters.is_some() {
                characters.expect("non-null function pointer")(
                    (*ctxt).userData,
                    &raw mut buf as *mut xmlChar,
                    nbchar,
                );
            }
        }
    }
    nbchar = 0 as c_int;
    let base = (*input).base;
    let end = (*input).end;
    if input_cur.offset_from(base) as c_long > (2 as c_int * INPUT_CHUNK) as c_long
        && (end.offset_from(input_cur) as c_long) < (2 as c_int * INPUT_CHUNK) as c_long
    {
        xmlParserShrink(ctxt as xmlParserCtxtPtr);
    }
}
cur = htmlCurrentChar(ctxt as xmlParserCtxtPtr, &raw mut l);

